script:
export const meta = {
  name: "ssb-brief",
  description: "3-paragraph brief on solid-state batteries",
  phases: [
    { name: "research", title: "Parallel research on commercialization, technology, and market" },
    { name: "synthesis", title: "Synthesize into 3-paragraph brief with sources" }
  ]
};

const research = await parallel(
  agent({
    prompt: `You are a battery-industry analyst. Give 4-6 concise bullet points on the latest commercialization progress for solid-state batteries as of 2024-2025: key companies (Toyota, QuantumScape, Solid Power, Samsung SDI, CATL, Factorial, Nio/WeLion), announced timelines, pilot/production milestones, and any vehicles or products shipping with solid-state or semi-solid cells. For each bullet, append a credible source URL (manufacturer press release page, Reuters/Bloomberg/FT article, or reputable trade outlet). Only cite URLs you are confident exist; prefer stable domains.`
  }),
  agent({
    prompt: `You are a battery-science researcher. Give 4-6 concise bullet points on core technical advances and remaining challenges in solid-state battery technology as of 2024-2025: solid electrolyte chemistries (sulfide, oxide, polymer), lithium-metal anode issues (dendrites, interface resistance, cycling), manufacturing/scalability hurdles, and notable recent lab breakthroughs. For each bullet, append a credible source URL (Nature/Science/Joule article, arXiv, or reputable tech outlet summary). Only cite URLs you are confident exist.`
  }),
  agent({
    prompt: `You are a clean-energy market analyst. Give 4-6 concise bullet points on the market outlook and competitive landscape for solid-state batteries: projected market size and growth, cost trajectory vs. conventional Li-ion, automotive OEM partnerships, and analyst forecasts for mainstream adoption timing. For each bullet, append a credible source URL (BloombergNEF, SNE Research, Goldman Sachs, IEA, or reputable business/energy outlet). Only cite URLs you are confident exist.`
  })
);

const brief = await agent({
  prompt: `Synthesize the following research into a 3-paragraph brief on the current state of solid-state batteries. Paragraph 1: commercialization progress & timelines. Paragraph 2: technical advances & remaining challenges. Paragraph 3: market outlook & adoption forecast. Keep it tight, factual, non-hyped. After the three paragraphs, add a "Sources" section listing the URLs provided, deduplicated, one per line. If any source seems speculative or unverifiable, drop it. Research:\n\n${JSON.stringify(research, null, 2)}`
});

return brief;
